/// λ, the GLV endomorphism scalar: `λ³ ≡ 1 (mod n)`, and `λ·(x, y) = (β·x, y)`.
///
/// The value libsecp256k1 publishes (`secp256k1_const_lambda`); the test below
/// re-derives every table row through it rather than trusting the script that
/// consumed it.
pub const LAMBDA: &str = "0x5363ad4cc05c30e0a5261c028812645a122e22ea20816678df02967c1b23bd72";

#[cfg(test)]
mod tests {
    extern crate std;

    use k256::elliptic_curve::ops::MulByGenerator;
    use k256::elliptic_curve::sec1::ToEncodedPoint;
    use k256::{ProjectivePoint, Scalar};

    use super::*;

    fn scalar_from_hex(hex: &str) -> Scalar {
        use k256::elliptic_curve::PrimeField;
        let body = hex.strip_prefix("0x").expect("the constants carry 0x");
        let mut bytes = [0u8; 32];
        for (i, chunk) in body.as_bytes().chunks(2).enumerate() {
            bytes[i] =
                u8::from_str_radix(core::str::from_utf8(chunk).expect("ascii"), 16).expect("hex");
        }
        Scalar::from_repr(bytes.into()).expect("the constant is a canonical scalar")
    }

    fn assert_is(point: &ProjectivePoint, (x, y): (&str, &str)) {
        let encoded = point.to_affine().to_encoded_point(false);
        let got_x = hex::encode(encoded.x().expect("not identity"));
        let got_y = hex::encode(encoded.y().expect("not identity"));
        assert_eq!(got_x, x.strip_prefix("0x").expect("prefixed"));
        assert_eq!(got_y, y.strip_prefix("0x").expect("prefixed"));
    }

    #[test]
    fn every_g_table_entry_is_the_odd_multiple_it_claims() {
        for (i, entry) in G_ODD.iter().enumerate() {
            let k = Scalar::from(2 * i as u64 + 1);
            assert_is(&ProjectivePoint::mul_by_generator(&k), *entry);
        }
    }

    #[test]
    fn every_lambda_table_entry_is_the_endomorphism_image_it_claims() {
        let lambda = scalar_from_hex(LAMBDA);
        for (i, entry) in LAMBDA_G_ODD.iter().enumerate() {
            let k = lambda * Scalar::from(2 * i as u64 + 1);
            assert_is(&ProjectivePoint::mul_by_generator(&k), *entry);
        }
    }

    #[test]
    fn the_two_tables_share_their_y_coordinates() {
        // The endomorphism moves x and keeps y, so a mismatched row pairing
        // would show here even if both tables were individually correct.
        for (g, lg) in G_ODD.iter().zip(LAMBDA_G_ODD.iter()) {
            assert_eq!(g.1, lg.1);
        }
    }
}
